with valid as (select id, order_id, quantity, unit_price, coalesce(quantity, 0) as quantity_filled, cast(unit_price as int) as unit_price_int from order_items where unit_price <= 280), base as (select id, order_id, unit_price, quantity_filled, unit_price_int, unit_price + unit_price_int as unit_price_plus_unit_price_int from valid where quantity_filled < 56), cleaned as (select *, coalesce(unit_price, 0) as unit_price_filled from base where quantity_filled >= 26), enriched as (select id, order_id, unit_price, quantity_filled, unit_price_int, unit_price_plus_unit_price_int, unit_price_filled, ntile(5) over (partition by order_id order by unit_price_int, id) as unit_price_int_bucket, lag(unit_price_int, 2, 0) over (partition by order_id order by unit_price_int, id) as prev_unit_price_int, cume_dist() over (partition by order_id order by quantity_filled desc) as quantity_filled_cume_dist, ntile(10) over (partition by order_id order by quantity_filled, id) as quantity_filled_bucket, sum(unit_price_int) over (partition by order_id) as order_id_sum_unit_price_int from cleaned), enriched_order_items as (select *, last_value(quantity_filled_bucket) ignore nulls over w_running as last_known_quantity_filled_bucket, first_value(order_id_sum_unit_price_int) ignore nulls over (order by unit_price, id rows between unbounded preceding and current row) as first_known_order_id_sum_unit_price_int, min(prev_unit_price_int) over (partition by order_id) as order_id_min_prev_unit_price_int from enriched window w_running as (partition by order_id order by unit_price_plus_unit_price_int, id rows between unbounded preceding and current row)), metrics as (select id, order_id, unit_price, quantity_filled, unit_price_int, unit_price_plus_unit_price_int, unit_price_filled, unit_price_int_bucket, prev_unit_price_int, quantity_filled_cume_dist, quantity_filled_bucket, order_id_sum_unit_price_int, last_known_quantity_filled_bucket, first_known_order_id_sum_unit_price_int, order_id_min_prev_unit_price_int, sum(quantity_filled_bucket) over (partition by order_id order by order_id_sum_unit_price_int, id rows between unbounded preceding and current row) as cumulative_quantity_filled_bucket, first_value(unit_price_filled, true) over (partition by order_id order by unit_price, id rows between unbounded preceding and current row) as first_known_unit_price_filled, last_value(quantity_filled_cume_dist) ignore nulls over (order by last_known_quantity_filled_bucket, id rows between unbounded preceding and current row) as last_known_quantity_filled_cume_dist, lag(unit_price_filled, 1) over (partition by order_id order by order_id_min_prev_unit_price_int, id) as prev_unit_price_filled, dense_rank() over (partition by order_id order by unit_price_plus_unit_price_int desc nulls last) as unit_price_plus_unit_price_int_dense_rank from enriched_order_items), valid_order_items as (select *, unit_price_int_bucket - first_known_unit_price_filled as unit_price_int_bucket_minus_first_known_unit_price_filled from metrics where prev_unit_price_filled < 70) select id, unit_price, unit_price_int, unit_price_plus_unit_price_int, unit_price_filled, prev_unit_price_int, quantity_filled_cume_dist, quantity_filled_bucket, last_known_quantity_filled_bucket from valid_order_items
